support_ticket_routing::alternatives::v1.text:
{
  "alternatives": [
    {
      "id": "OPT-01",
      "name": "No change — keep rules engine v3.3 as the primary router",
      "kind": "no_change",
      "description": "Continue with the 404-rule production engine and the normal maintenance cadence. No new intervention is funded this half; the team keeps measuring routing accuracy and time-to-resolution and revisits at FY27 planning. This is the honest baseline every other option must beat, and it fully respects D-2025-06 and D-2025-11.",
      "horizon": "core",
      "supporting": [
        {
          "evidence_id": "EV-68cdd2b1",
          "quote": "**D-2025-06 — Rules-based routing retained as the primary routing mechanism.** Rationale: rules are inspectable, cheap to change, and auditable line by line.",
          "locator": "Decisions carried forward"
        },
        {
          "evidence_id": "EV-46e54a4b",
          "quote": "The `routing_decision_log` table already meets this requirement and is the required destination for any replacement router.",
          "locator": "Audit trail"
        }
      ],
      "opposing": [
        {
          "evidence_id": "EV-79d2ae90",
          "quote": "Our assessment is that keyword rules have reached their ceiling on this ticket mix.",
          "locator": "Assessment, 2026-06-30"
        },
        {
          "evidence_id": "EV-133fecfa",
          "quote": "value: 22.6",
          "locator": "2026-Q2 median_time_to_resolution_hours, all"
        }
      ],
      "assessments": [
        {
          "dimension": "customer_reach",
          "state": "assessed",
          "summary": "The status quo touches every ticket: roughly 41,880 exported rows per quarter pass through the router.",
          "citations": [
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Ticket volume is up 16.7% year over year, from 35,900 to 41,880 per quarter.",
              "locator": "Current position"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "financial_impact",
          "state": "assessed",
          "summary": "Holding still leaves the FY26 goal unmet and drifting the wrong way: median TTR is 22.6 h against a 12 h target, p90 96.4 h against a sub-60 h target.",
          "citations": [
            {
              "evidence_id": "EV-133fecfa",
              "quote": "value: 22.6",
              "locator": "2026-Q2 median_time_to_resolution_hours"
            },
            {
              "evidence_id": "EV-2c64d766",
              "quote": "value: 96.4",
              "locator": "2026-Q2 p90_time_to_resolution_hours"
            },
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Reduce median time-to-resolution for customer support tickets from 21 hours to 12 hours by the end of FY26.",
              "locator": "Annual goals"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "strategic_customer_importance",
          "state": "cannot_assess",
          "summary": "No customer-satisfaction read on reassignment exists, so the customer cost of leaving churn in place cannot be quantified. Missing: a populated csat_after_reassignment series.",
          "citations": [
            {
              "evidence_id": "EV-fc7594e3",
              "quote": "note: synthetic - field exists but was never populated",
              "locator": "csat_after_reassignment"
            }
          ]
        },
        {
          "dimension": "spend",
          "state": "assessed",
          "summary": "No incremental capital, but the status quo is not free: maintaining the ordered rule list now costs roughly a working day of engineering review per rule change.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "review time for a single rule change has grown from under an hour in 2024 to roughly a working day",
              "locator": "Assessment"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "product_usage",
          "state": "cannot_assess",
          "summary": "How agents actually respond to routing decisions is unobservable today. Missing: any disagreement or override-reason signal.",
          "citations": [
            {
              "evidence_id": "EV-3e2d12e8",
              "quote": "There is no record of an agent disagreeing with a routing decision, only of the reassignment itself.",
              "locator": "What is not in these datasets"
            }
          ]
        },
        {
          "dimension": "strategic_alignment",
          "state": "assessed",
          "summary": "Perfectly aligned with the carried-forward routing and ML-spend decisions, and directly misaligned with the stated FY26 responsiveness goals.",
          "citations": [
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "**D-2025-11 — No new machine-learning infrastructure spend in FY26.**",
              "locator": "Decisions carried forward"
            },
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Reduce p90 time-to-resolution below 60 hours.",
              "locator": "Annual goals"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "delivery_effort",
          "state": "assessed",
          "summary": "Nil beyond the existing two-engineer review process for routine rule changes.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "Rule changes are reviewed by two support engineers and deployed behind a flag.",
              "locator": "Rule change process"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "risk",
          "state": "assessed",
          "summary": "Low execution risk, high goal-miss risk: three expansion passes produced 0.6 points of accuracy in twelve months while reassignments per ticket rose from 0.58 to 0.62.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "Three expansion passes since v3 have moved queue-level accuracy from 70.8% to 71.4%, a gain of 0.6 percentage points across twelve months and 176 added rules.",
              "locator": "Assessment"
            },
            {
              "evidence_id": "EV-c6a26def",
              "quote": "value: 0.62",
              "locator": "2026-Q2 reassignments_per_ticket"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "evidence_confidence",
          "state": "assessed",
          "summary": "High confidence in what the baseline does, because the replayed rules figure reproduces the published production number exactly.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "The replayed rules figure of 71.2% matches the production figure for 2026-Q1 exactly.",
              "locator": "Results"
            }
          ],
          "support_level": "strong"
        }
      ],
      "why_not_selected": "Defensible only if the organisation is prepared to miss the FY26 TTR goals: the engine owner states the rules approach has reached its ceiling and the trend on median TTR, p90 and reassignment churn is adverse."
    },
    {
      "id": "OPT-02",
      "name": "Defer the routing decision to FY27 planning, pending review of D-2025-11",
      "kind": "defer",
      "description": "Take no routing action this year and place two items on the FY27 planning agenda: whether D-2025-11's rationale still applies now that Modelyard exists, and whether D-2025-06 should still name rules as primary. Meanwhile only the cheapest measurement work continues.",
      "horizon": "core",
      "supporting": [
        {
          "evidence_id": "EV-68cdd2b1",
          "quote": "Rationale: the FY26 platform budget was committed to the store fulfilment programme, and standing up dedicated model-serving infrastructure for support was quoted at $180k of capital plus two engineers.",
          "locator": "D-2025-11"
        }
      ],
      "opposing": [
        {
          "evidence_id": "EV-ac98dec8",
          "quote": "It hosts CPU inference for models up to 2 GB and already carries two models for the fulfilment team. Adding a third model requires no new infrastructure and no new vendor.",
          "locator": "Model serving"
        }
      ],
      "assessments": [
        {
          "dimension": "customer_reach",
          "state": "assessed",
          "summary": "No change in reach this year; every ticket continues to be routed by the current engine at current volumes.",
          "citations": [
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Ticket volume is up 16.7% year over year, from 35,900 to 41,880 per quarter.",
              "locator": "Current position"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "financial_impact",
          "state": "assessed",
          "summary": "Deferral concedes the FY26 targets; misrouted tickets currently resolve in 51.8 h median against 14.2 h for first-time-right tickets, and that gap persists for another year.",
          "citations": [
            {
              "evidence_id": "EV-8576e42f",
              "quote": "note: tickets reassigned at least once before resolution - synthetic",
              "locator": "2026-Q2 median_time_to_resolution_hours, misrouted"
            },
            {
              "evidence_id": "EV-b7f6b080",
              "quote": "value: 14.2",
              "locator": "2026-Q2 median_time_to_resolution_hours, correctly_routed"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "strategic_customer_importance",
          "state": "cannot_assess",
          "summary": "Cannot judge the customer cost of a further year of churn without satisfaction data. Missing: csat_after_reassignment values.",
          "citations": [
            {
              "evidence_id": "EV-fc7594e3",
              "quote": "note: synthetic - field exists but was never populated",
              "locator": "csat_after_reassignment"
            }
          ]
        },
        {
          "dimension": "spend",
          "state": "assessed",
          "summary": "Zero incremental spend, which is the main argument for it, and it keeps cost per ticket — a board measure — untouched.",
          "citations": [
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Cost per ticket is a board-reported measure this year.",
              "locator": "Priorities and constraints"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "product_usage",
          "state": "cannot_assess",
          "summary": "No usage signal is created by deferring. Missing: any instrumented trial in production.",
          "citations": []
        },
        {
          "dimension": "strategic_alignment",
          "state": "assessed",
          "summary": "Aligned with budget discipline but weakly aligned with the stated goal set; the specific premise of the spend freeze is documented as no longer binding for CPU inference on Modelyard.",
          "citations": [
            {
              "evidence_id": "EV-ac98dec8",
              "quote": "Adding a third model requires no new infrastructure and no new vendor.",
              "locator": "Model serving"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "delivery_effort",
          "state": "assessed",
          "summary": "Effectively nil; the trial report and its offline evaluation are already written and would carry into FY27 review.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "The held-out set is every labelled ticket created between 2026-01-01 and 2026-03-31: 4,800 tickets.",
              "locator": "Split"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "risk",
          "state": "assessed",
          "summary": "Main risk is staleness: the offline result is measured on a January–March window whose mix is atypical, so a year's delay may require re-running the evaluation before it can be trusted.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "The held-out period is January to March. Ticket mix in that window is shaped by the post-holiday returns peak. Whether accuracy holds across the rest of the year is untested.",
              "locator": "Limitations"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "evidence_confidence",
          "state": "assessed",
          "summary": "The evidence that nothing yet has been tested against TTR is explicit, which is a genuine argument for not committing spend on inference alone.",
          "citations": [
            {
              "evidence_id": "EV-06ff9877",
              "quote": "No intervention has been tested with time-to-resolution as its primary measure.",
              "locator": "Not attempted"
            }
          ],
          "support_level": "strong"
        }
      ],
      "why_not_selected": "Cheaper and slower than OPT-03, which buys the missing TTR measurement inside FY26 without breaching either carried-forward decision."
    },
    {
      "id": "OPT-03",
      "name": "Shadow-mode live measurement of the classifier against the rules engine",
      "kind": "further_research",
      "description": "Run the trialled classifier on Modelyard alongside the rules engine on live tickets. The rules engine's decision is applied; both decisions are logged to routing_decision_log; accuracy and time-to-resolution are compared on the same tickets. No customer is routed by the model, so D-2025-06 stands and no human-review requirement is engaged.",
      "horizon": "adjacent",
      "supporting": [
        {
          "evidence_id": "EV-8dc73255",
          "quote": "A shadow period before any traffic is switched: run the classifier alongside the rules engine on live tickets, apply the rules engine's decision, log both, and measure accuracy and time-to-resolution against the same tickets. The platform already supports this.",
          "locator": "Recommendation from the trial team"
        },
        {
          "evidence_id": "EV-79d2ae90",
          "quote": "Shadow evaluation is supported: the engine can run alongside a second router, with both decisions logged and only one applied. This was used for the v3 rollout in November 2024.",
          "locator": "Rule change process"
        },
        {
          "evidence_id": "EV-ac98dec8",
          "quote": "Modelyard runs in-region, and its training pipelines run in-region.",
          "locator": "Model serving"
        }
      ],
      "opposing": [
        {
          "evidence_id": "EV-ac98dec8",
          "quote": "The platform accepts one automated assignment per ticket. Every move after the first must be agent-initiated.",
          "locator": "Routing at ticket creation"
        },
        {
          "evidence_id": "EV-3e2d12e8",
          "quote": "Ticket events reach the analytics warehouse with a lag of up to 26 hours.",
          "locator": "Analytics lag"
        }
      ],
      "assessments": [
        {
          "dimension": "customer_reach",
          "state": "assessed",
          "summary": "Observes all live traffic while affecting no customer, because the applied decision remains the rules engine's.",
          "citations": [
            {
              "evidence_id": "EV-ac98dec8",
              "quote": "It can be run in shadow alongside a second router: both produce a decision, one is applied, both are logged.",
              "locator": "Rules engine"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "financial_impact",
          "state": "cannot_assess",
          "summary": "Shadow mode produces no TTR benefit by construction; it produces the measurement that would size the benefit. Missing: exactly the production TTR comparison this option is designed to create.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "It did not measure time-to-resolution, because no ticket was routed by the classifier in production and no customer was affected.",
              "locator": "Limitations"
            }
          ]
        },
        {
          "dimension": "strategic_customer_importance",
          "state": "cannot_assess",
          "summary": "No customer impact and no satisfaction instrument, so importance cannot be evidenced. Missing: populated csat_after_reassignment.",
          "citations": [
            {
              "evidence_id": "EV-fc7594e3",
              "quote": "note: synthetic - field exists but was never populated",
              "locator": "csat_after_reassignment"
            }
          ]
        },
        {
          "dimension": "spend",
          "state": "assessed",
          "summary": "No new vendor and no new infrastructure: a 340 MB CPU model fits Modelyard's existing 2 GB limit. Running and retraining cost is nonetheless unquantified and should be metered during the shadow period.",
          "citations": [
            {
              "evidence_id": "EV-ac98dec8",
              "quote": "It hosts CPU inference for models up to 2 GB and already carries two models for the fulfilment team. Adding a third model requires no new infrastructure and no new vendor.",
              "locator": "Model serving"
            },
            {
              "evidence_id": "EV-8dc73255",
              "quote": "We have not estimated the cost of running or retraining this model in production.",
              "locator": "Limitations"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "product_usage",
          "state": "assessed",
          "summary": "Predictions land in the existing log table with version, predicted queue and confidence, so usage and disagreement rates against the applied decision become measurable for the first time.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "Every trial prediction was written to the existing `routing_decision_log` table with the model version, the predicted queue and the model's confidence, in the same schema the rules engine writes to. No change to that table was required.",
              "locator": "Model and serving"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "strategic_alignment",
          "state": "assessed",
          "summary": "Does not disturb either carried-forward decision — rules remain primary and applied — while producing the evidence FY27 planning needs; routing is also explicitly out of scope for the human-review requirement.",
          "citations": [
            {
              "evidence_id": "EV-46e54a4b",
              "quote": "Internal classification that produces no customer-facing text is out of scope for this requirement. Routing a ticket to a queue is internal classification.",
              "locator": "Automated customer-facing text"
            },
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "**D-2025-06 — Rules-based routing retained as the primary routing mechanism.**",
              "locator": "Decisions carried forward"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "delivery_effort",
          "state": "assessed",
          "summary": "Modest: shadow mode is an existing capability used for the v3 rollout, latency fits the 400 ms budget with a 118 ms p99, and no log schema change is required.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "Median inference time on the trial hardware was 41 ms per ticket, CPU only, with a 99th percentile of 118 ms.",
              "locator": "Model and serving"
            },
            {
              "evidence_id": "EV-ac98dec8",
              "quote": "The support platform requests a routing decision once, at ticket creation, and waits at most 400 ms for it.",
              "locator": "Routing at ticket creation"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "risk",
          "state": "assessed",
          "summary": "Low customer risk since nothing is applied. Two real limits: shadow mode cannot fully attribute TTR change because no shadow decision is acted on, and the 26-hour analytics lag means no same-day read.",
          "citations": [
            {
              "evidence_id": "EV-3e2d12e8",
              "quote": "Same-day measurement of any intervention is not possible; the earliest reliable read on a change is the following day.",
              "locator": "Analytics lag"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "evidence_confidence",
          "state": "assessed",
          "summary": "Strongest evidential footing of any option: a time-split offline evaluation on 4,800 unseen tickets already exists, with a 60.1% misroute reduction to be confirmed or refuted live.",
          "citations": [
            {
              "evidence_id": "EV-8dc73255",
              "quote": "Overall the classifier routed 88.5% of held-out tickets to the correct queue against the rules engine's 71.2%. Misroutes fall from 1,382 to 552, a reduction of 60.1%.",
              "locator": "Results on the held-out set"
            }
          ],
          "support_level": "strong"
        }
      ],
      "why_not_selected": "Not rejected; it is the lowest-risk way to close the one gap everybody agrees on, but on its own it delivers no TTR improvement inside the measurement window."
    },
    {
      "id": "OPT-04",
      "name": "Rules change: consume the customer-selected category across all five queues",
      "kind": "rules_based_automation",
      "description": "Rather than a fourth keyword expansion pass, rewrite the ordered list so the customer-selected category from the shipped guided picker is consulted for all five queues instead of two. This harvests an improvement already paid for on the intake side.",
      "horizon": "core",
      "supporting": [
        {
          "evidence_id": "EV-06ff9877",
          "quote": "The guided picker shipped to all customers on 2025-10-02. It improved the category customers select and did not measurably improve routing, because the rules engine consults the customer-selected category for only two of the five queues.",
          "locator": "Intake form redesign"
        },
        {
          "evidence_id": "EV-06ff9877",
          "quote": "The share of tickets where the customer-selected category matched the resolving queue rose from 57.1% to 64.3%.",
          "locator": "Intake form redesign"
        }
      ],
      "opposing": [
        {
          "evidence_id": "EV-79d2ae90",
          "quote": "Two of the three passes above introduced ordering regressions that had to be patched within a fortnight of deployment.",
          "locator": "Assessment"
        },
        {
          "evidence_id": "EV-79d2ae90",
          "quote": "We do not expect a fourth expansion pass to behave differently from the three before it.",
          "locator": "Assessment"
        }
      ],
      "assessments": [
        {
          "dimension": "customer_reach",
          "state": "assessed",
          "summary": "Applies to every incoming ticket, and the guided picker input is present for all customers since October 2025.",
          "citations": [
            {
              "evidence_id": "EV-06ff9877",
              "quote": "The guided picker shipped to all customers on 2025-10-02.",
              "locator": "Intake form redesign"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "financial_impact",
          "state": "cannot_assess",
          "summary": "The category signal is 64.3% concordant with the resolving queue, but no test has measured what routing on it does to accuracy or TTR. Missing: an A/B or shadow evaluation of category-driven rules.",
          "citations": [
            {
              "evidence_id": "EV-06ff9877",
              "quote": "Queue-level routing accuracy was 72.0% in the treatment arm against 71.3% in the control arm. That difference is not statistically meaningful.",
              "locator": "Intake form redesign"
            }
          ]
        },
        {
          "dimension": "strategic_customer_importance",
          "state": "cannot_assess",
          "summary": "No per-segment or satisfaction breakdown available. Missing: csat and any account-level segmentation of misroutes.",
          "citations": [
            {
              "evidence_id": "EV-fc7594e3",
              "quote": "note: synthetic - field exists but was never populated",
              "locator": "csat_after_reassignment"
            }
          ]
        },
        {
          "dimension": "spend",
          "state": "assessed",
          "summary": "No capital, but real engineering time: rule review has risen to about a working day per change against a 404-rule ordered list.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "There are 404 rules in production.",
              "locator": "What the routing engine is"
            },
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "review time for a single rule change has grown from under an hour in 2024 to roughly a working day",
              "locator": "Assessment"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "product_usage",
          "state": "assessed",
          "summary": "Every rule evaluation is already logged with rule id, engine version and matched inputs, so adoption of the new rules is directly observable.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "The decision made by every rule evaluation is written to `routing_decision_log` with the rule id, the engine version, and the inputs it matched on.",
              "locator": "Rule change process"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "strategic_alignment",
          "state": "assessed",
          "summary": "Fully compliant with D-2025-06 and the inspectability rationale behind it, and needs no ML spend.",
          "citations": [
            {
              "evidence_id": "EV-68cdd2b1",
              "quote": "Rationale: rules are inspectable, cheap to change, and auditable line by line.",
              "locator": "D-2025-06"
            }
          ],
          "support_level": "strong"
        },
        {
          "dimension": "delivery_effort",
          "state": "assessed",
          "summary": "Moderate and regression-prone: reordering an ordered decision list is exactly where two of three previous passes broke.",
          "citations": [
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "Each new rule must be checked against the rules already in the ordered list for conflicts",
              "locator": "Assessment"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "risk",
          "state": "assessed",
          "summary": "Risk that customer-selected categories are wrong in about a third of cases and would propagate misroutes; mitigable by shadow evaluation before applying.",
          "citations": [
            {
              "evidence_id": "EV-06ff9877",
              "quote": "The share of tickets where the customer-selected category matched the resolving queue rose from 57.1% to 64.3%.",
              "locator": "Intake form redesign"
            },
            {
              "evidence_id": "EV-79d2ae90",
              "quote": "Shadow evaluation is supported: the engine can run alongside a second router, with both decisions logged and only one applied.",
              "locator": "Rule change process"
            }
          ],
          "support_level": "moderate"
        },
        {
          "dimension": "evidence_confidence",
          "state": "assessed",
          "summary": "The diagnosis is well evidenced from a randomised test of 16,802 tickets; the remedy's effect size is not.",
          "citations": [
            {
              "evidence_id": "EV-06ff9877",
              "quote": "Randomised at the customer level over three weeks: 8,412 tickets in the treatment arm and 8,390 in the control arm.",
              "locator": "Intake form redesign"
            }
          ],
          "support_level": "moderate"
        }
      ],
      "why_not_selected": "Plausible cheap win and the best remaining rules-side move, but the engine owner's documented view is that keyword rules have hit their ceiling, and no measurement links this change to TTR."
    },
    {
      "id": "OPT-05",
      "name": "Human triage desk for all intake streams",
      "kind": "process_change",
